Identify the Table 1 name column and Table 2 name/value columns from the header row. Build a first-match map from Table 2 names to their first Value 1, skipping placeholder rows. Write the mapped value for each Table 1 name in rows 8–11 into D8:D11 as plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title
if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]
vws = vals[sheet_name]

def norm(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def key(v):
    n = norm(v)
    if n is None:
        return None
    return str(n)

def is_placeholder(s):
    return not any(ch.isalnum() for ch in s)

col1 = col2 = val1 = None
header_row = 6

for r in range(1, min(vws.max_row, 20) + 1):
    for c in range(1, vws.max_column + 1):
        v = norm(vws.cell(r, c).value)
        if v is None:
            continue
        vl = v.lower()
        if vl == "column 1":
            col1 = c
            header_row = r
        elif vl == "column 2":
            col2 = c
            header_row = r

if col2 is not None:
    for c in range(col2 + 1, vws.max_column + 1):
        v = norm(vws.cell(header_row, c).value)
        if v is not None and v.lower() == "value 1":
            val1 = c
            break

if col1 is None:
    col1 = 3
if col2 is None:
    col2 = 12
if val1 is None:
    val1 = col2 + 1

start = header_row + 1
first_val = {}

for r in range(start, vws.max_row + 1):
    name = norm(vws.cell(r, col2).value)
    if name is None:
        continue
    if isinstance(name, str) and is_placeholder(name):
        continue
    k = key(name)
    if k is None:
        continue
    if k not in first_val:
        first_val[k] = norm(vws.cell(r, val1).value)

result = []
for r in range(8, 12):
    name = norm(ws.cell(r, col1).value)
    val = first_val.get(key(name)) if name is not None else None
    ws.cell(r, 4).value = val
    result.append(val)

wb.save(OUT)

print("header_row", header_row, "cols", col1, col2, val1)
print("first_val", first_val)
print("D8:D11", result)
